import { Component, forwardRef, input } from '@angular/core';
import { FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import { NzRadioModule } from 'ng-zorro-antd/radio';
import { HrmControl } from '../shared/hrm-control';
import { HrmOption } from '../shared/hrm-option';

/** hrm-radio-group — CVA, options-driven. style='default'|'button'. */
@Component({
  selector: 'hrm-radio-group',
  imports: [FormsModule, NzRadioModule],
  template: `
    <nz-radio-group
      [ngModel]="value()"
      (ngModelChange)="emit($event)"
      [nzDisabled]="disabled()"
      [nzButtonStyle]="'solid'"
      [nzSize]="size() === 'sm' ? 'small' : size() === 'lg' ? 'large' : 'default'">
      @for (o of options(); track o.value) {
        @if (variant() === 'button') {
          <label nz-radio-button [nzValue]="o.value" [nzDisabled]="o.disabled">{{ o.label }}</label>
        } @else {
          <label nz-radio [nzValue]="o.value" [nzDisabled]="o.disabled">{{ o.label }}</label>
        }
      }
    </nz-radio-group>
  `,
  host: { class: 'hrm-radio-group' },
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => HrmRadioGroup), multi: true }],
})
export class HrmRadioGroup extends HrmControl<unknown> {
  readonly options = input<HrmOption[]>([]);
  readonly variant = input<'default' | 'button'>('default');
  readonly size = input<'sm' | 'md' | 'lg'>('md');
}
